-- =============================================================================
-- seed_pasos_metodo.sql  ·  PASOS/CAMPOS por metodo desde ANALFIELDS (StarLIMS)
-- GENERADO por 07_migracion/build_seed_pasos.py (NO editar a mano).
-- Fuente: ANALFIELDS.csv de 'CSV LIMS 2026-07-02'. Todo al tenant IDIC.
-- Aplicar DESPUES de packages/db/align_pasos_metodo.sql (y catalogo_v2 + seed):
--     psql "$DATABASE_URL" -f packages/db/seed_pasos_metodo.sql
-- Filas de paso candidatas (pre-join a cat_metodo): 6332
--   TESTCODE distintos ......... 3924
--   filas saltadas sin PROPIEDAD 138
--   filas dedup (tc,orden,prop). 309
-- NOTA: el nº REAL insertado depende de cuantos TESTCODE existan en
--       cat_metodo (join por clave natural). ON CONFLICT DO NOTHING.
-- =============================================================================

BEGIN;

-- Resolver el tenant IDIC (falla explicitamente si no existe).
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM tenant WHERE codigo='IDIC') THEN
    RAISE EXCEPTION 'No existe tenant IDIC; ejecute el seed base antes.';
  END IF;
END $$;

CREATE TEMP TABLE stg_paso (
  metodo_codigo text, orden int, nombre text, tipo_dato text, formato text
) ON COMMIT DROP;

COPY stg_paso (metodo_codigo, orden, nombre, tipo_dato, formato) FROM stdin WITH (FORMAT csv, NULL '');
