-- Carga resolviendo tenant IDIC + cat_metodo por clave natural (TESTCODE).
WITH t AS (SELECT id FROM tenant WHERE codigo='IDIC')
INSERT INTO paso_metodo (tenant_id, cat_metodo_id, orden, nombre, tipo_dato, formato)
SELECT t.id, m.id, s.orden, s.nombre, s.tipo_dato, NULLIF(s.formato,'')
FROM stg_paso s CROSS JOIN t
JOIN cat_metodo m ON m.tenant_id = (SELECT id FROM t) AND m.codigo = s.metodo_codigo
ON CONFLICT (tenant_id, cat_metodo_id, orden, nombre) DO NOTHING;

COMMIT;

